import React from 'react';
import './BookCard.css';

function BookCard({ book }) {
  const coverUrl = book.cover_i
    ? `https://covers.openlibrary.org/b/id/${book.cover_i}-M.jpg`
    : 'https://via.placeholder.com/150x220?text=No+Cover';

  return (
    <div className="book-card">
      <img src={coverUrl} alt={book.title} className="book-cover" />
      <h3 className="book-title">{book.title}</h3>
      <p className="book-author"><strong>Author:</strong> {book.author_name?.join(', ') || 'Unknown'}</p>
      <p className="book-year"><strong>Published:</strong> {book.first_publish_year || 'N/A'}</p>
      <div className="book-actions">
        <button className="book-btn">Add to Cart</button>
        <button className="book-btn">Add to Wishlist</button>
      </div>
    </div>
  );
}

export default BookCard;
